import argparse,hashlib,json,pathlib,sys
from fractions import Fraction
P=pathlib.Path(__file__).resolve().parent
H=lambda b:hashlib.sha256(b).hexdigest()
def check(fixture,out):
 d=json.loads(fixture.read_text());c=json.loads((P/'CONTRACT.json').read_text());F=Fraction;n=F(d['material_amount']['value']);q=F(d['energy_per_mole']['value']);frac=F(d['capture_fraction']['value']);mass=F(d['water_mass']['value']);cp=F(d['heat_capacity']['value']); expected_total=n*q*1000;expected_transfer=expected_total*frac;expected_temp=expected_transfer/mass/cp
 chem=json.loads((out/'03_chemistry_energy.json').read_text());transfer=json.loads((out/'04_transfer.json').read_text());temp=json.loads((out/'05_temperature.json').read_text());math=F(chem['energy_release']['value'])==expected_total and F(transfer['transferred_energy']['value'])==expected_transfer and F(temp['temperature_change']['value'])==expected_temp; units=chem['energy_release']['unit']=='J' and transfer['transferred_energy']['unit']=='J' and temp['temperature_change']['unit']=='K' and all(d[k]['unit']==v for k,v in {'material_amount':'mol','energy_per_mole':'kJ/mol','capture_fraction':'1','water_mass':'kg','heat_capacity':'J/(kg*K)'}.items());inputs=H(fixture.read_bytes())==c['fixture_sha256'];ex=json.loads((P/'expected_hashes.json').read_text()); observed={name:H((out/name).read_bytes()) for name in ex}; identity=observed==ex;commit=json.loads((out/'07_commitment.json').read_text());consistent=commit['artifacts']=={name:H((out/name).read_bytes()) for name in ex if name!='07_commitment.json'};status='PASS' if math and units and inputs and identity and consistent else 'REJECT';return {'status':status,'math':math,'units':units,'frozen_fixture':inputs,'hashes':identity,'commitment_consistent':consistent}
if __name__=='__main__':
 a=argparse.ArgumentParser();a.add_argument('--fixture',type=pathlib.Path,default=P/'fixture.json');a.add_argument('--out',type=pathlib.Path,required=True);x=a.parse_args();r=check(x.fixture,x.out);print(json.dumps(r,sort_keys=True));sys.exit(0 if r['status']=='PASS' else 1)
